import sys,difflib,re
L=open(sys.argv[1],encoding='utf-8').read().split('\n')
i=0;n=0
while i<len(L):
    l=L[i]
    if l.startswith('@@'):
        print('\n=== ',l[:80]);i+=1;continue
    if l.startswith('-') and not l.startswith('---'):
        minus=[];plus=[]
        while i<len(L) and L[i].startswith('-'): minus.append(L[i][1:]);i+=1
        while i<len(L) and L[i].startswith('+'): plus.append(L[i][1:]);i+=1
        for a,b in zip(minus,plus):
            ta=re.split(r'(\s+)',a);tb=re.split(r'(\s+)',b)
            sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
            out=[]
            for op,i1,i2,j1,j2 in sm.get_opcodes():
                if op=='equal':
                    s=''.join(ta[i1:i2])
                    out.append(s if len(s)<120 else s[:50]+' ... '+s[-50:])
                else:
                    if i2>i1: out.append('[-'+''.join(ta[i1:i2])+'-]')
                    if j2>j1: out.append('{+'+''.join(tb[j1:j2])+'+}')
            print('#',a[:60]);print(''.join(out));print()
        for b in plus[len(minus):]: print('ADDED:',b)
        for a in minus[len(plus):]: print('REMOVED:',a[:200])
        continue
    if l.startswith('+') and not l.startswith('+++'):
        print('ADDED:',l[1:]);
    i+=1
EOF

